import React, { useState } from 'react';
import axios from 'axios';
import { useNavigate, Link } from 'react-router-dom';

function Register() {
  const [nom, setNom] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [role, setRole] = useState('student');
  const [classId, setClassId] = useState('');
  const navigate = useNavigate();

  const handleSubmit = async (e) => {
    e.preventDefault();
    console.log({ nom, email, password, role, classId }); // debug frontend
    try {
      axios.post('http://localhost:5000/api/auth/register', 
 {
        nom,
        email,
        password,
        role,
        class_id: classId || null
      });
      alert('Compte créé avec succès !');
      navigate('/');
    } catch (err) {
      console.error(err.response?.data || err.message);
      alert('Erreur lors de l\'inscription: ' + (err.response?.data?.msg || err.message));
    }
  };

  return (
    <div style={{ maxWidth: 400, margin: 'auto', padding: 20 }}>
      <h2>Inscription</h2>
      <form onSubmit={handleSubmit}>
        <input placeholder="Nom" value={nom} onChange={e => setNom(e.target.value)} required style={{ display:'block', margin:'10px 0', width:'100%' }} />
        <input type="email" placeholder="Email" value={email} onChange={e => setEmail(e.target.value)} required style={{ display:'block', margin:'10px 0', width:'100%' }} />
        <input type="password" placeholder="Mot de passe" value={password} onChange={e => setPassword(e.target.value)} required style={{ display:'block', margin:'10px 0', width:'100%' }} />
        <select value={role} onChange={e => setRole(e.target.value)} style={{ display:'block', margin:'10px 0', width:'100%' }}>
          <option value="student">Étudiant</option>
          <option value="prof">Professeur</option>
        </select>
        {role === 'student' && (
          <input placeholder="Classe ID" value={classId} onChange={e => setClassId(e.target.value)} style={{ display:'block', margin:'10px 0', width:'100%' }} />
        )}
        <button type="submit" style={{ display:'block', margin:'10px 0' }}>S'inscrire</button>
      </form>
      <p>Déjà un compte ? <Link to="/">Se connecter</Link></p>
    </div>
  );
}

export default Register;
